@startuml

class Customer {
  + name : string
  + phoneNumber : string
}

class Table {
  + numberOfSeats : int
  + isSmoking : boolean
}

class Reservation {
  + day : date
  + time : time
  + numberOfPeople : int
}

class Waiter {
  + name : string
  + yearsOfService : int
}

class Bill {
  + finalAmount : double
}

class Dish {
  + name : string
  + unitPrice : double
}

Customer "1" -- "*" Reservation
Reservation "*" -- "1..*" Table
Waiter "1" -- "*" Customer
Customer "1" -- "1" Bill
Bill "1" *-- "*" Dish

@enduml

